// === Tab: tree ===
/* let Tweak of *@*http://www.openprocessing.org/sketch/144159*@* */
/* !do not delete the line above, required for linking your tweak if you upload again */
class pathfinder {
  lastLocation;
  location;
  velocity;
  diameter;
  isFinished;
  constructor() {
    location = new PVector(width/2, height);
    lastLocation = new PVector(location.x, location.y);
    velocity = new PVector(100, -10);
    diameter = random(300, 20);
    isFinished = false;
  }
  constructor(pathfinder parent) {
    location = parent.location.get();
    lastLocation = parent.lastLocation.get();
    velocity = parent.velocity.get();
    diameter = parent.diameter * 0.62;
    isFinished = parent.isFinished;
    parent.diameter = diameter;
  }
  function update() {

    if(location.x > -10 & location.x < width + 10 & location.y > -10 & location.y < height + 10) {
      lastLocation.set(location.x, location.y);
      if (diameter > 0.2) {
        count ++;
        let bump = new PVector(random(-1, 1), random(-1, 1));
        velocity.normalize();
        bump.mult(0.2);
        velocity.mult(0.8);
        velocity.add(bump);
        velocity.mult(random(5, 10));
        location.add(velocity);
        if (random(0, 1) < 0.2) { // control length
          paths = (pathfinder[]) append(paths, new constructor(this));
        }
      } else {
        if(!isFinished) {
          isFinished = true;
          noStroke();
          fill(240, 230, 150, 100);
          ellipse(location.x, location.y, 10, 10);
          stroke(200, 0, 0, 200);
        }
      }
    }
  }
}
pathfinder[] paths;
let num;
let count;
function setup() {
  createCanvas(800, 600);
  background(250);
  ellipseMode(CENTER);
  stroke(200, 0, 0, 200);
  smooth();
  num = 2;
  count = 0;
  paths = new Array(num);
  for(i = 0; i < num; i++) paths[i] = new pathfinder();
}

function draw() {
//  println(count);
//  println(paths.length);
  for (i = 0; i < paths.length; i++) {
    let loc = paths[i].location;
    let lastLoc = paths[i].lastLocation;
    strokeWeight(paths[i].diameter);
    line(lastLoc.x, lastLoc.y, loc.x, loc.y);
    paths[i].update();
  }
}
function mousePressed() {
  background(250);
  count = 0;
  paths = new Array(num);
  for(i = 0; i < num; i++) paths[i] = new pathfinder();

}

